def collega_aventi(apps, schema_editor):
    """Gli operatori già nominati che sono capi in elenco diventano componenti
    del comitato elettorale collegati al loro avente diritto."""
    OperatoreVoto = apps.get_model("assemblee", "OperatoreVoto")
    AventeDiritto = apps.get_model("assemblee", "AventeDiritto")
    for operatore in OperatoreVoto.objects.filter(
        avente__isnull=True, utente__codice_socio__isnull=False
    ).select_related("utente"):
        avente = AventeDiritto.objects.filter(
            assemblea_id=operatore.assemblea_id,
            codice_socio=operatore.utente.codice_socio,
            eliminato_il__isnull=True,
        ).first()
        if avente is not None:
            operatore.avente = avente
            operatore.save(update_fields=["avente"])


